// MINIMUM VIABLE INCOME — the smallest monthly income that holds, in TIERS, on the WORST month.
//
// "How much do I need to earn?" has no single answer, and pretending it does is what makes the
// answer useless. Needing $2,100 to keep the lights on and $4,300 to stop the debt growing are both
// true and they lead to completely different decisions. So this reports a ladder:
//
//   SURVIVAL  what cannot lapse — housing, utilities, insurance, healthcare, debt minimums, and the
//             groceries and transport that get you to work. Everything else is given up, and the
//             list of what you gave up is part of the answer.
//   CURRENT   survival plus every standing obligation, so nothing goes delinquent. This is the
//             headline: it is the line below which NEW damage starts.
//   STABLE    current plus ordinary discretionary spending, so nothing is drawn from savings.
//   PROGRESS  stable plus a deliberate payment above the minimums.
//
// THE HEADLINE IS THE WORST MONTH, NOT THE AVERAGE, and that is the same discipline the runway uses.
// An annual insurance renewal makes one month cost $900 more than the other eleven; an income that
// covers the median clears every month except the one it does not, and that month is a missed
// payment. The median is reported too, because the gap between the two IS the saving-up problem.
import { type Money, money, sum } from "@/features/finance/lib/money";
import { monthOf } from "@/features/finance/lib/txn";
import { type ObligationCalendar, monthsBetween } from "@/features/finance/lib/obligations";
import { type SpendingAnalysis, categorise } from "@/features/finance/lib/spending";
import type { IncomeProjection } from "@/features/finance/lib/projection";

export type Tier = "survival" | "current" | "stable" | "progress";

/**
 * What cannot be given up without losing something that costs more than it saves — a home, a car
 * that gets you to work, cover against a bill that would end this. DATA, so it can be argued with.
 */
export const ESSENTIAL_CATEGORIES: ReadonlySet<string> = new Set([
  "housing",
  "utilities",
  "insurance",
  "healthcare",
  "childcare",
  "groceries",
  "transport",
  "fuel",
]);

export interface TierRequirement {
  readonly tier: Tier;
  /** The usual month. What the ladder looks like most of the time. */
  readonly typicalMonth: Money;
  /** The month that costs most. THIS is what an income has to clear. */
  readonly worstMonth: Money;
  readonly worstMonthName: string;
  /** In this tier's words, what it buys. */
  readonly includes: readonly string[];
  /** What is given up at this tier, so the trade is visible rather than implied. */
  readonly excludes: readonly string[];
}

export interface TierGap {
  readonly tier: Tier;
  /** POSITIVE shortfall against the LOW income band in the worst month. Zero when already clear. */
  readonly shortfall: Money;
  readonly clears: boolean;
}

export interface ViableIncome {
  readonly currency: string;
  readonly from: string;
  readonly to: string;
  readonly tiers: readonly TierRequirement[];
  /** The absolute floor: what cannot lapse. */
  readonly floor: TierRequirement;
  /** The line below which NEW damage starts — the number to quote when asked one. */
  readonly headline: TierRequirement;
  /** Against the projection's LOW band, tier by tier. Absent when there is no projection to compare. */
  readonly gaps?: readonly TierGap[];
  readonly notes: readonly string[];
}

export interface ViableOptions {
  /** A deliberate payment above the minimums — what turns holding on into getting out. */
  readonly progressTarget?: Money;
}

const median = (xs: number[]): number => {
  if (!xs.length) return 0;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2);
};

/** An obligation nothing can place is treated as ESSENTIAL — for a floor, over-stating is the safe
 *  direction and under-stating is a missed payment. It is named rather than quietly promoted. */
const obligationIsEssential = (label: string, kind: string): { essential: boolean; placed: boolean } => {
  // A missed minimum is a credit event, not a cancelled luxury. It is essential regardless.
  if (kind === "minimum") return { essential: true, placed: true };
  const category = categorise(label);
  if (!category) return { essential: true, placed: false };
  return { essential: ESSENTIAL_CATEGORIES.has(category), placed: true };
};

export function minimumViableIncome(
  calendar: ObligationCalendar,
  spending: SpendingAnalysis,
  currency: string,
  projection?: IncomeProjection,
  opts: ViableOptions = {},
): ViableIncome {
  const { progressTarget = money(0, currency) } = opts;
  const notes: string[] = [];
  const months = monthsBetween(calendar.from, calendar.to);

  const unplaced = new Set<string>();
  const essentialByMonth = new Map<string, number>();
  const allByMonth = new Map<string, number>();
  for (const m of months) {
    essentialByMonth.set(m, 0);
    allByMonth.set(m, 0);
  }
  for (const o of calendar.obligations) {
    const m = o.date.slice(0, 7);
    if (!allByMonth.has(m)) continue;
    allByMonth.set(m, allByMonth.get(m)! + o.amount.minor);
    const { essential, placed } = obligationIsEssential(o.label, o.kind);
    if (!placed) unplaced.add(o.label);
    if (essential) essentialByMonth.set(m, essentialByMonth.get(m)! + o.amount.minor);
  }
  if (unplaced.size) {
    notes.push(
      `${unplaced.size} obligation(s) matched no category and are counted as ESSENTIAL — for a floor, over-stating costs you a bigger target and under-stating costs you a missed payment: ${[...unplaced].join(", ")}`,
    );
  }

  // VARIABLE SPENDING IS SUMMED FROM THE SAME PARTS ON BOTH SIDES, deliberately. Medians do not add,
  // so `spending.variableMonthly` (a median of totals) and the sum of per-category medians are
  // different numbers — and mixing the two would let the essential half exceed the whole, which
  // would put the ladder out of order for reasons nobody could see in the output.
  // VARIABLE CATEGORIES ONLY, and this is the whole of the fix that was needed here. `categories`
  // covers every outflow that was spent, fixed charges included — so rent appears BOTH there and on
  // the obligation calendar, and summing the two counted it twice. Every tier came out overstated by
  // the whole of the rent, which tells somebody they need to earn far more than they do.
  const essentialVariable = spending.variableCategories
    .filter((c) => ESSENTIAL_CATEGORIES.has(c.category))
    .reduce((n, c) => n + c.typicalMonth.minor, 0);
  const categorisedVariable = spending.variableCategories.reduce((n, c) => n + c.typicalMonth.minor, 0);

  const uncatByMonth = new Map<string, number>();
  for (const t of spending.uncategorised) {
    const m = monthOf(t.date);
    uncatByMonth.set(m, (uncatByMonth.get(m) ?? 0) + -t.amount.minor);
  }
  const uncategorisedVariable = median([...uncatByMonth.values()]);
  const allVariable = categorisedVariable + uncategorisedVariable;

  if (Math.abs(allVariable - spending.variableMonthly.minor) > 0) {
    notes.push(
      `variable spending here is ${allVariable} minor units, against ${spending.variableMonthly.minor} reported by the spending analysis — medians do not add, and this figure is built from the same parts as the essential half so the ladder cannot come out of order`,
    );
  }

  const build = (tier: Tier, per: (m: string) => number, includes: string[], excludes: string[]): TierRequirement => {
    const totals = months.map(per);
    let worstAt = 0;
    for (let i = 1; i < totals.length; i++) if (totals[i] > totals[worstAt]) worstAt = i;
    return {
      tier,
      typicalMonth: money(median(totals), currency),
      worstMonth: money(totals.length ? totals[worstAt] : 0, currency),
      worstMonthName: months[worstAt] ?? calendar.from.slice(0, 7),
      includes,
      excludes,
    };
  };

  const survival = build(
    "survival",
    (m) => essentialByMonth.get(m)! + essentialVariable,
    ["housing, utilities, insurance, healthcare and childcare", "every debt MINIMUM — a missed one is a credit event", "groceries, transport and fuel"],
    ["every subscription and membership", "dining, entertainment and shopping", "anything paid above a minimum"],
  );
  const current = build(
    "current",
    (m) => allByMonth.get(m)! + essentialVariable,
    ["everything in survival", "every standing obligation, so nothing goes delinquent"],
    ["dining, entertainment and shopping", "anything paid above a minimum"],
  );
  const stable = build(
    "stable",
    (m) => allByMonth.get(m)! + allVariable,
    ["everything in current", "ordinary discretionary spending, so nothing is drawn from savings"],
    ["anything paid above a minimum — the debt stops growing but does not shrink"],
  );
  const progress = build(
    "progress",
    (m) => allByMonth.get(m)! + allVariable + progressTarget.minor,
    ["everything in stable", `a deliberate ${progressTarget.minor} minor units a month above the minimums`],
    [],
  );

  if (progressTarget.minor === 0) {
    notes.push("no progress target was given, so PROGRESS equals STABLE — a stable position is one where the debt stops growing, not one where it shrinks");
  }
  const spread = current.worstMonth.minor - current.typicalMonth.minor;
  if (spread > 0) {
    notes.push(
      `${current.worstMonthName} costs ${spread} minor units more than the usual month — an income that only clears the median misses that month, and the gap between the two is the amount to have put aside before it arrives`,
    );
  }

  const tiers = [survival, current, stable, progress];

  return {
    currency,
    from: calendar.from,
    to: calendar.to,
    tiers,
    floor: survival,
    // CURRENT is the headline. Survival means letting things lapse, which has consequences that
    // outlast the month it saved; current is the line below which NEW damage starts.
    headline: current,
    ...(projection?.projectable
      ? {
          gaps: tiers.map((t): TierGap => {
            const band = projection.months.find((b) => b.month === t.worstMonthName) ?? projection.months[0];
            const income = band?.low.minor ?? 0;
            const short = Math.max(0, t.worstMonth.minor - income);
            return { tier: t.tier, shortfall: money(short, currency), clears: short === 0 };
          }),
        }
      : {}),
    notes,
  };
}

/** The tiers a projected income already clears — what is actually secured today. */
export const clearedTiers = (v: ViableIncome): readonly Tier[] =>
  (v.gaps ?? []).filter((g) => g.clears).map((g) => g.tier);

/** One sentence, in the terms the question was asked in. */
export function summariseViable(v: ViableIncome): string {
  const gap = v.gaps?.find((g) => g.tier === "current");
  const base = `${v.headline.worstMonth.minor} minor units a month keeps everything current, measured on ${v.headline.worstMonthName} — the worst month, not the average`;
  if (!gap) return base;
  return gap.clears
    ? `${base}; the low income band already clears it`
    : `${base}; the low income band is short by ${gap.shortfall.minor}`;
}

/** Every tier's requirement is at least the one below it. Stated as a function so a caller can
 *  assert it on real data, not only in a test. */
export function ladderIsOrdered(v: ViableIncome): boolean {
  return v.tiers.every((t, i) => i === 0 || t.worstMonth.minor >= v.tiers[i - 1].worstMonth.minor);
}

/** What the whole ladder costs over the window, tier by tier — the annual framing. */
export const overWindow = (v: ViableIncome, t: TierRequirement, months: number): Money =>
  sum(new Array(months).fill(t.typicalMonth), v.currency);

