import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import type { Txn } from "@/features/finance/lib/txn";
import type { Recurring } from "@/features/finance/lib/recurring";
import type { AccountPosition, Position } from "@/features/finance/lib/position";
import type { IncomeProjection, MonthBand } from "@/features/finance/lib/projection";
import { unverifiedLedger } from "@/features/finance/lib/reconcile";
import { buildCalendar } from "@/features/finance/lib/obligations";
import { analyseSpending } from "@/features/finance/lib/spending";
import {
  ESSENTIAL_CATEGORIES,
  clearedTiers,
  ladderIsOrdered,
  minimumViableIncome,
  summariseViable,
} from "@/features/finance/lib/viable";

// SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");
const tx = (date: string, description: string, major: number, account = "checking"): Txn => ({
  date,
  description,
  amount: usd(major),
  account,
});

const recur = (over: Partial<Recurring>): Recurring => ({
  key: "x",
  label: "X",
  account: "checking",
  cadence: "monthly",
  typical: usd(10),
  annualised: usd(120),
  occurrences: 6,
  firstSeen: "2026-01-01",
  lastSeen: "2026-06-01",
  regularity: 1,
  amountStability: 1,
  lapsed: false,
  ...over,
});

const RENT = recur({ key: "rent landlord", label: "RENT PAYMENT LANDLORD", typical: usd(1500) });
const POWER = recur({ key: "city electric", label: "CITY ELECTRIC UTILITY", typical: usd(120) });
const NETFLIX = recur({ key: "netflix", label: "NETFLIX.COM", typical: usd(18), account: "card" });
const INSURANCE = recur({
  key: "acme insurance",
  label: "ACME INSURANCE ANNUAL",
  typical: usd(900),
  cadence: "annual",
  lastSeen: "2025-09-03",
});

const card: AccountPosition = {
  account: "card",
  institution: "Northwind Card",
  kind: "credit",
  balance: usd(-2000),
  asOf: "2026-06-30",
  rolledForward: 0,
  isDebt: true,
  owed: usd(2000),
  minimumPayment: usd(75),
};

const position: Position = {
  asOf: "2026-06-30",
  currency: "USD",
  accounts: [card],
  netWorth: usd(-800),
  liquid: usd(1200),
  totalDebt: usd(2000),
  dailyInterest: usd(1),
  minimumsDue: usd(75),
  complete: true,
  problems: [],
  provenance: "reconciled · synthetic",
};

const calendar = () =>
  buildCalendar([RENT, POWER, NETFLIX, INSURANCE], position, { from: "2026-07-01", to: "2026-12-31" });

/** Five months of spending so three are whole and a median means something. */
const spendMonths = ["2026-02", "2026-03", "2026-04", "2026-05", "2026-06"];
const rows: Txn[] = spendMonths.flatMap((m) => [
  tx(`${m}-08`, "SAFEWAY GROCERY", -300),
  tx(`${m}-14`, "SHELL OIL 4471", -100),
  tx(`${m}-19`, "CORNER CAFE", -80),
  tx(`${m}-24`, "TARGET STORE", -120),
]);
const spending = () => analyseSpending(unverifiedLedger(rows, "2026-06-30", "synthetic fixture"), position, [], "USD");

const band = (month: string, low: number): MonthBand => ({ month, low: usd(low), expected: usd(low + 500), high: usd(low + 900) });
const projection = (low: number): IncomeProjection => ({
  projectable: true,
  months: ["2026-07", "2026-08", "2026-09", "2026-10", "2026-11", "2026-12"].map((m) => band(m, low)),
  total: { low: usd(0), expected: usd(0), high: usd(0) },
  assumptions: [],
  excluded: [],
  sourcesUsed: 1,
});

describe("the ladder is ORDERED, and that is not an accident", () => {
  it("never lets a lower tier cost more than a higher one", () => {
    const v = minimumViableIncome(calendar(), spending(), "USD");
    expect(v.tiers.map((t) => t.tier)).toEqual(["survival", "current", "stable", "progress"]);
    expect(ladderIsOrdered(v)).toBe(true);
    for (let i = 1; i < v.tiers.length; i++) {
      expect(v.tiers[i].worstMonth.minor).toBeGreaterThanOrEqual(v.tiers[i - 1].worstMonth.minor);
      expect(v.tiers[i].typicalMonth.minor).toBeGreaterThanOrEqual(v.tiers[i - 1].typicalMonth.minor);
    }
  });

  it("builds variable spending from the SAME parts on both sides, because medians do not add", () => {
    // The essential half is a sum of per-category medians; the whole must be too. Mixing that with
    // the spending analysis's median-of-totals can make the part exceed the whole, which puts the
    // ladder out of order for a reason nobody could see in the output.
    const v = minimumViableIncome(calendar(), spending(), "USD");
    const essentialOnly = spending()
      .categories.filter((c) => ESSENTIAL_CATEGORIES.has(c.category))
      .reduce((n, c) => n + c.typicalMonth.minor, 0);
    const all = spending().categories.reduce((n, c) => n + c.typicalMonth.minor, 0);
    expect(essentialOnly).toBeLessThan(all);
    expect(v.tiers[2].typicalMonth.minor - v.tiers[1].typicalMonth.minor).toBe(all - essentialOnly);
  });
});

describe("medians genuinely do not add", () => {
  // A fixture where the two ways of computing "variable spending" REALLY disagree, so the rule is
  // pinned by arithmetic rather than by a fixture that happened to make them equal. Whole months
  // are March, April and May; groceries run 900/100/300 and dining 100/900/80, so the per-category
  // medians are 300 and 100 (sum 400) while the median of the monthly TOTALS is 1000.
  const lumpy = () => {
    const g = { "2026-02": 300, "2026-03": 900, "2026-04": 100, "2026-05": 300, "2026-06": 300 };
    const d = { "2026-02": 80, "2026-03": 100, "2026-04": 900, "2026-05": 80, "2026-06": 80 };
    const txns = Object.keys(g).flatMap((m) => [
      tx(`${m}-08`, "SAFEWAY GROCERY", -g[m as keyof typeof g]),
      tx(`${m}-19`, "CORNER CAFE", -d[m as keyof typeof d]),
    ]);
    return analyseSpending(unverifiedLedger(txns, "2026-06-30", "synthetic fixture"), position, [], "USD");
  };

  it("the two figures disagree, and the ladder uses the one built from the same parts", () => {
    const s = lumpy();
    expect(s.variableMonthly.minor).toBe(usd(1000).minor);
    const perCategory = s.categories.reduce((n, c) => n + c.typicalMonth.minor, 0);
    expect(perCategory).toBe(usd(400).minor);

    const v = minimumViableIncome(calendar(), s, "USD");
    // STABLE minus CURRENT is the non-essential variable half. Built from per-category medians it is
    // dining's 100; taking the difference against a median-of-totals would make it 700 and could put
    // the essential half above the whole.
    expect(v.tiers[2].typicalMonth.minor - v.tiers[1].typicalMonth.minor).toBe(usd(100).minor);
    expect(ladderIsOrdered(v)).toBe(true);
    expect(v.notes.join(" ")).toContain("medians do not add");
  });
});

describe("survival — what is given up is part of the answer", () => {
  const v = () => minimumViableIncome(calendar(), spending(), "USD");

  it("keeps housing, utilities and the debt minimum; drops the subscription", () => {
    const survival = v().floor;
    const current = v().tiers[1];
    // NETFLIX is the only non-essential obligation, so it is the whole difference in a normal month.
    expect(current.typicalMonth.minor - survival.typicalMonth.minor).toBe(usd(18).minor);
    expect(survival.excludes.join(" ")).toContain("subscription");
  });

  it("keeps a debt MINIMUM whatever it is labelled, because a missed one is a credit event", () => {
    const withNoMinimum = buildCalendar([RENT], undefined, { from: "2026-07-01", to: "2026-12-31" });
    const bare = minimumViableIncome(withNoMinimum, spending(), "USD");
    const withMin = minimumViableIncome(
      buildCalendar([RENT], position, { from: "2026-07-01", to: "2026-12-31" }),
      spending(),
      "USD",
    );
    expect(withMin.floor.typicalMonth.minor - bare.floor.typicalMonth.minor).toBe(usd(75).minor);
  });

  it("keeps a STORE CARD's minimum, even though the card is named after a shop", () => {
    // Store cards are named after retailers, so a minimum labelled "Target RedCard minimum" reads as
    // `shopping` to the category table and would be dropped from survival as a luxury. It is a debt
    // minimum: missing it is a credit event, and the kind decides that, not the name.
    const storeCard: AccountPosition = { ...card, account: "store", institution: "Target RedCard", minimumPayment: usd(40) };
    const storePosition: Position = { ...position, accounts: [storeCard] };
    const bare = minimumViableIncome(
      buildCalendar([RENT], undefined, { from: "2026-07-01", to: "2026-12-31" }),
      spending(),
      "USD",
    );
    const withStore = minimumViableIncome(
      buildCalendar([RENT], storePosition, { from: "2026-07-01", to: "2026-12-31" }),
      spending(),
      "USD",
    );
    expect(withStore.floor.typicalMonth.minor - bare.floor.typicalMonth.minor).toBe(usd(40).minor);
    // And it is not surviving on the uncategorised fallback — the table DOES place this label.
    expect(withStore.notes.join(" ")).not.toContain("Target RedCard minimum");
  });

  it("counts an obligation it cannot categorise as ESSENTIAL, and says so", () => {
    const mystery = recur({ key: "zzq holdings", label: "ZZQ HOLDINGS", typical: usd(60) });
    const c = buildCalendar([RENT, mystery], undefined, { from: "2026-07-01", to: "2026-12-31" });
    const v2 = minimumViableIncome(c, spending(), "USD");
    const without = minimumViableIncome(buildCalendar([RENT], undefined, { from: "2026-07-01", to: "2026-12-31" }), spending(), "USD");
    // Over-stating costs you a bigger target; under-stating costs you a missed payment.
    expect(v2.floor.typicalMonth.minor - without.floor.typicalMonth.minor).toBe(usd(60).minor);
    expect(v2.notes.join(" ")).toContain("ZZQ HOLDINGS");
    expect(v2.notes.join(" ")).toContain("ESSENTIAL");
  });
});

describe("the headline is the WORST month, not the average", () => {
  it("measures on the month with the annual renewal in it", () => {
    // September carries the $900 insurance. An income covering the median clears every month except
    // that one, and that one is a missed payment.
    const v = minimumViableIncome(calendar(), spending(), "USD");
    expect(v.headline.worstMonthName).toBe("2026-09");
    expect(v.headline.worstMonth.minor - v.headline.typicalMonth.minor).toBe(usd(900).minor);
    expect(v.headline.worstMonth.minor).toBeGreaterThan(v.headline.typicalMonth.minor);
  });

  it("names the gap between the two as the amount to have put aside", () => {
    const v = minimumViableIncome(calendar(), spending(), "USD");
    expect(v.notes.join(" ")).toContain("2026-09");
    expect(v.notes.join(" ")).toContain("put aside before it arrives");
  });

  it("is CURRENT, not survival — survival means letting something lapse", () => {
    const v = minimumViableIncome(calendar(), spending(), "USD");
    expect(v.headline.tier).toBe("current");
    expect(v.floor.tier).toBe("survival");
    expect(summariseViable(v)).toContain("worst month, not the average");
  });
});

describe("the gap against a real income band", () => {
  it("measures each tier against the LOW band in that tier's worst month", () => {
    const v = minimumViableIncome(calendar(), spending(), "USD", projection(2200));
    const current = v.gaps!.find((g) => g.tier === "current")!;
    expect(current.shortfall.minor).toBe(v.headline.worstMonth.minor - usd(2200).minor);
    expect(current.clears).toBe(false);
  });

  it("reports zero, not a negative, when income already clears a tier", () => {
    const v = minimumViableIncome(calendar(), spending(), "USD", projection(20000));
    expect(v.gaps!.every((g) => g.clears)).toBe(true);
    expect(v.gaps!.every((g) => g.shortfall.minor === 0)).toBe(true);
    expect(clearedTiers(v)).toEqual(["survival", "current", "stable", "progress"]);
    expect(summariseViable(v)).toContain("already clears it");
  });

  it("clears the lower rungs before the higher ones", () => {
    const v = minimumViableIncome(calendar(), spending(), "USD", projection(3000));
    const shortfalls = v.gaps!.map((g) => g.shortfall.minor);
    for (let i = 1; i < shortfalls.length; i++) expect(shortfalls[i]).toBeGreaterThanOrEqual(shortfalls[i - 1]);
  });

  it("omits the gaps entirely rather than comparing against nothing", () => {
    const none: IncomeProjection = {
      projectable: false,
      reason: "2 whole month(s) of history",
      months: [],
      assumptions: [],
      excluded: [],
      sourcesUsed: 0,
    };
    const v = minimumViableIncome(calendar(), spending(), "USD", none);
    expect(v.gaps).toBeUndefined();
    expect(clearedTiers(v)).toEqual([]);
    expect(summariseViable(v)).not.toContain("clears");
  });
});

describe("progress — stable is not the same as getting out", () => {
  it("equals stable with no target, and says a stable position only stops the debt growing", () => {
    const v = minimumViableIncome(calendar(), spending(), "USD");
    expect(v.tiers[3].worstMonth.minor).toBe(v.tiers[2].worstMonth.minor);
    expect(v.notes.join(" ")).toContain("stops growing, not one where it shrinks");
  });

  it("adds a deliberate payment above the minimums when one is asked for", () => {
    const v = minimumViableIncome(calendar(), spending(), "USD", undefined, { progressTarget: usd(400) });
